# -*- coding: utf-8 -*-

import streamlit as st
import streamlit.components.v1 as components

APP_HTML = '<!doctype html>\n<html lang="ko">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<style>\nhtml,body{margin:0;padding:0;width:100%;height:100%;background:#f4f7f5;overflow:hidden}\n.view{display:none;width:100%;height:1500px;border:0}\n.view.active{display:block}\n</style>\n</head>\n<body>\n<iframe id="dashFrame" class="view active" sandbox="allow-scripts allow-forms allow-modals allow-same-origin allow-popups"></iframe>\n<iframe id="memberFrame" class="view" sandbox="allow-scripts allow-forms allow-modals allow-same-origin allow-popups"></iframe>\n<script>\nconst dash = document.getElementById(\'dashFrame\');\nconst mem = document.getElementById(\'memberFrame\');\nfunction decodeHtml(b64) {\n  const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));\n  return new TextDecoder(\'utf-8\').decode(bytes);\n}\ndash.srcdoc = decodeHtml(\'\');\nmem.srcdoc = decodeHtml(\'\');\nfunction show(page) {\n  const members = page === \'members\';\n  dash.classList.toggle(\'active\', !members);\n  mem.classList.toggle(\'active\', members);\n  window.scrollTo(0, 0);\n}\nwindow.addEventListener(\'message\', (e) => {\n  if (e.data && e.data.type === \'mg-nav\') show(e.data.page);\n});\n</script>\n</body>\n</html>'

st.set_page_config(page_title="MG 금융 데이터", layout="wide", initial_sidebar_state="collapsed")

st.markdown("""
<style>
.block-container {padding:0; max-width:100%;}
header[data-testid="stHeader"] {background:transparent;}
</style>
""", unsafe_allow_html=True)

components.html(APP_HTML, height=1500, scrolling=False)
